function buscarContraejemplo(semilla, intentos) {
  let estado = semilla;
  for (let i = 0; i < intentos; i++) {
    estado = siguiente(estado);
    const lista = listaAleatoria(estado, 5);
    if (!cumplePropiedad(lista, menorEsperaConError(lista))) {
      return lista.join(",");
    }
  }
  return "ninguno";
}
